            ("विशाल नयन मुख चन्द्र सुहावा । रूप देखि सुर नर मन भावा ॥ ३ ॥", "आपके विशाल नेत्र और चन्द्रमा के समान सुंदर मुखमण्डल की शोभा को देखकर देवता और मनुष्य मुग्ध हो जाते हैं।"),
            ("कानन कुण्डल मुकुट विराजै । कर धनु-बाण महा छवि छाजै ॥ ४ ॥", "आपके कानों में दिव्य कुण्डल और मस्तक पर रत्नजटित मुकुट सुशोभित है; हाथों में धनुष-बाण धारण किए आपकी छवि अलौकिक है।"),
            ("पीताम्बर तन पर छवि पावै । देखि छटा मुनि ध्यान लगावै ॥ ५ ॥", "आपके नीलमेघ-श्याम शरीर पर पीताम्बर वस्त्र अत्यंत शोभायमान है, जिसे देखकर मुनिजन समाधिस्थ हो जाते हैं।"),
            ("विश्वामित्र मुनि जबहिं पुकारा । ताड़का मारी यज्ञ उबारा ॥ ६ ॥", "जब महर्षि विश्वामित्र ने राक्षसों के उपद्रव से रक्षा हेतु पुकारा, तब आपने ताड़का और सुबाहु का वध कर उनके यज्ञ की रक्षा की।"),
            ("मुनि पत्नी अहल्या को तारा । चरण रज से कीन्ह उधारा ॥ ७ ॥", "आपने अपने चरण-कमलों की पावन रज का स्पर्श कराकर पाषाण बनी मुनि-पत्नी अहल्या का उद्धार कर दिया।"),
            ("जनक सभा धनु तोरि कठोरा । सीता ब्याहि चले प्रिय मोरा ॥ ८ ॥", "आपने राजा जनक की सभा में शिवजी के कठोर पिनाक धनुष को तोड़कर माता जानकी का पाणिग्रहण किया।"),
            ("परशुराम का मान मिटाया । निज बल पौरुष प्रगट दिखाया ॥ ९ ॥", "आपने अपने शील और तेज से क्रोधी परशुराम जी का मान दूर कर अपना साक्षात् विष्णु-स्वरूप प्रकट किया।"),
            ("मातु कैकेयी वचन संभारा । चौदह वर्ष वनहिं पग धारा ॥ १० ॥", "पिता दशरथ के सत्य और माता कैकेयी के वचनों का पालन करने हेतु आपने चौदह वर्षों के लिए वन-गमन स्वीकार किया।"),
            ("संग लखन सीता सुखकारी । चित्रकूट में कुटी संवारी ॥ ११ ॥", "साथ में लक्ष्मण जी और माता सीता के संग आपने चित्रकूट के पावन पर्वत पर सुंदर पर्णकुटी बनाकर वास किया।"),
            ("दण्डक वन में असुर विडारे । शूर्पणखा के कान उतारे ॥ १२ ॥", "दण्डकारण्य में आपने ऋषियों को निर्भय करने हेतु खर-दूषण आदि राक्षसों का वध किया और शूर्पणखा को दण्डित किया।"),
            ("माया मृग मारी रघुराई । रावण सीता हरण कराई ॥ १३ ॥", "जब आपने कपटी मारीच रूपी माया-मृग का वध किया, तब पीछे से दुष्ट रावण ने माता सीता का हरण कर लिया।"),
            ("जटायु गीध की गति प्रभु दीन्ही । शबरी के फल भक्ति रस लीन्ही ॥ १४ ॥", "आपने सीता-वियोग में प्राण त्यागने वाले जटायु को मोक्ष प्रदान किया और माता शबरी के प्रेमपूर्वक दिए जूठे बेरों को बड़े चाव से स्वीकार किया।"),
            ("सुग्रीवहिं सँग मित्रता कीनी । बालि मारि वानर पद दीनी ॥ १५ ॥", "आपने सुग्रीव के साथ अग्नि-साक्षी मित्रता की और अधर्मी बालि का वध करके सुग्रीव को किष्किन्धा का राज्य सौंपा।"),
            ("पवन सुवन को दूत पठाया । लंका जाय पता लगवाया ॥ १६ ॥", "आपने पवनपुत्र हनुमान जी को दूत बनाकर भेजा, जिन्होंने लंका में जाकर माता सीता का पता लगाया।"),
            ("सिन्धु बाँधि वानर दल लाये । लंका में रघुवीर सिधाये ॥ १७ ॥", "आपने विशाल समुद्र पर नल-नील द्वारा सेतु बंधवाया और समस्त वानर-भालू सेना सहित लंका पर चढ़ाई की।"),
            ("कुम्भकर्ण रावण संहारा । विभीषण को राज उदारा ॥ १८ ॥", "आपने कुम्भकर्ण, मेघनाद और लंकापति रावण जैसे महाबलियों का संहार किया और विभीषण को लंका का छत्र प्रदान किया।"),
            ("सीता लखन संग प्रभु आये । अवधपुरी सब मंगल छाये ॥ १९ ॥", "माता सीता और लक्ष्मण जी के संग जब आप पुष्पक विमान से अयोध्या लौटे, तो सम्पूर्ण अवधपुरी में आनंद-मंगलोत्सव छा गया।"),
            ("सिंहासन बैठे रघुराई । सुर नर मुनि सब शीश नवाई ॥ २० ॥", "जब आप अयोध्या के राजसिंहासन पर विराजमान हुए, तो समस्त देवताओं, मनुष्यों और मुनियों ने आपके चरणों में प्रणाम किया।"),
            ("राम राज बैठे त्रैलोका । हर्षित भए गए सब शोका ॥ २१ ॥", "श्रीराम के राजसिंहासन पर बैठते ही तीनों लोकों के प्राणी हर्षित हो गए और उनके समस्त प्रकार के शोक मिट गए।"),
            ("दैहिक दैविक भौतिक तापा । राम राज नहिं काहुहि ब्यापा ॥ २२ ॥", "रामराज्य में किसी भी प्राणी को दैहिक (शारीरिक रोग), दैविक (प्राकृतिक आपदा) और भौतिक (आपसी क्लेश) ताप नहीं व्यापते थे।"),
            ("अल्प मृत्यु नहिं कवनिउ पीरा । सब सुंदर सब बिरुज शरीरा ॥ २३ ॥", "उस पावन राज्य में किसी की अकाल मृत्यु नहीं होती थी, कोई रोगी नहीं था; सभी लोग सुंदर, स्वस्थ और धर्मात्मा थे।"),
            ("चरण कमल की महिमा भारी । नारद शारद गावत हारी ॥ २४ ॥", "आपके चरण-कमलों की महिमा अपार है, जिसका पार देवर्षि नारद और माता सरस्वती भी नहीं पा सकतीं।"),
            ("जो नर राम नाम लौ लावै । सो भव सागर सहजहिं पावै ॥ २५ ॥", "जो मनुष्य भगवान् श्रीराम के पावन नाम से अनन्य प्रेम करता है, वह इस भवसागर को सहज ही पार कर जाता है।"),
            ("रोग शोक संताप विडारो । हे रघुबीर हमहिं उबारो ॥ २६ ॥", "हे रघुकुल शिरोमणि! मेरे समस्त रोगों, शोकों और संतापों का नाश कीजिए और मेरा इस संसार से उद्धार कीजिए।"),
            ("शरणागत वत्सल रघुराया । मोहिं राखहु अपनी शीतल छाया ॥ २७ ॥", "हे शरणागतवत्सल प्रभु! मुझे अपने पावन चरणों की शीतल छाया में आश्रय प्रदान कीजिए।"),
            ("काम क्रोध मद लोभ हिलाओ । हृदय कमल में आन समाओ ॥ २८ ॥", "मेरे मन के काम, क्रोध, मद, लोभ आदि विकारों को समूल नष्ट कर मेरे हृदय-कमल में आकर निवास कीजिए।"),
            ("तुलसीदास प्रभु आस तुम्हारी । हरहु सकल दुख संकट भारी ॥ २९ ॥", "गोस्वामी तुलसीदास जी प्रार्थना करते हैं कि हे प्रभु! मुझे केवल आपकी ही आशा है; मेरे सभी दुःखों और भारी संकटों को हर लीजिए।"),
            ("जो यह राम चालीसा गावे । सो निश्चय सब सम्पत्ति पावे ॥ ३० ॥", "जो भी इस राम चालीसा का नित्य पाठ करता है, वह इस लोक में समस्त सुख-सम्पदा और अंत में परमधाम पाता है।"),
            ("पुत्र हीन को पुत्र सुहावन । निर्धन को धन देत पावन ॥ ३१ ॥", "आप निःसंतान को गुणवान संतान देते हैं और निर्धन को पवित्र धन-ऐश्वर्य प्रदान करते हैं।"),
            ("भूत पिशाच निकट नहिं आवैं । राम नाम जो निसिदिन गावैं ॥ ३२ ॥", "जो रात-दिन 'राम-राम' का पावन जाप करता है, भूत-पिशाच और अमंगलकारी शक्तियां उसके निकट भी नहीं आ सकतीं।"),
            ("चारों वेदन मर्म तुम्हारा । जानत सब जग देव उदारा ॥ ३३ ॥", "चारों वेदों में आपके ही धर्ममय स्वरूप का वर्णन है; सम्पूर्ण संसार आपको परम कृपालु व उदार जानता है।"),
            ("नित्त नेम करि पाठ सुनावे । सो नर सब सुख भोग लगावे ॥ ३४ ॥", "जो नियमपूर्वक नित्य यह चालीसा पाठ करता है, वह संसार के सम्पूर्ण सुखों का उपभोग करता है।"),
            ("सकल मनोरथ सिद्ध करंता । जय रघुवीर धीर गुणवंता ॥ ३५ ॥", "आप भक्तों के समस्त धर्मानुकूल मनोरथों को सिद्ध करने वाले हैं; हे परम धैर्यवान, गुणवान रघुवीर! आपकी जय हो।"),
            ("दीन दयाल दया निधि देवा । मोहिं दीजै निज पावन सेवा ॥ ३६ ॥", "हे दीनदयालु! हे दया के भण्डार! मुझे अपने चरणों की नित्य अनन्य सेवा का वरदान दीजिए।"),
            ("सदा रहो प्रभु अंग हमारे । जन्म मरण के बन्धन तारे ॥ ३७ ॥", "हे प्रभु! सदा मेरे संग रहिए और मुझे जन्म-मरण के सांसारिक बन्धन से मुक्त कर दीजिए।"),
            ("राम नाम जो जपै निरंतर । मिटै अविद्या ताके भीतर ॥ ३८ ॥", "जो निरंतर प्रभु राम के नाम का स्मरण करता है, उसके हृदय से अज्ञान और अविद्या का अंधकार मिट जाता है।"),
            ("प्रेम सहित जो पूजन कीन्हा । ताको प्रभु पद सहजहिं दीन्हा ॥ ३९ ॥", "जिसने भी निष्काम प्रेम से आपका पूजन किया, उसे आपने सहज ही अपना परम पद प्रदान कर दिया।"),
            ("राम चालीसा जो नित गावे । सो नर निश्चय मोक्षहि पावे ॥ ४० ॥", "जो मनुष्य इस श्री राम चालीसा का नित्य श्रद्धापूर्वक पाठ करता है, वह निश्चय ही परम मोक्ष को प्राप्त करता है।")
